/bin/zsh -lc "cat > src/server/repositories/issue-import-repository.ts <<'EOF'
import { and, count, eq, isNull, sql } from \"drizzle-orm\";
import { newId } from \"@/lib/id\";
import { wouldExceedLimit } from \"@/config/plan-limits\";
import { getDb, issueImports, issues, issueLabels, labels, members, users } from \"@/server/db\";
import { toIsoTimestamp } from \"@/types/common\";
import { toIssue } from \"./_mappers\";
import type { ImportIssuesInput } from \"@/schemas/issue-import\";
import type { PlanId } from \"@/types/billing\";
import type { LabelId, OrgId, ProjectId, UserId } from \"@/types/common\";
import type { Issue, IssueImportResult } from \"@/types/issue\";

export function findImport(orgId: OrgId, importKey: string): IssueImportResult | null {
  const row = getDb().select().from(issueImports).where(and(eq(issueImports.orgId, orgId), eq(issueImports.importKey, importKey))).get();
  return row ? { importKey, projectId: row.projectId as ProjectId, issues: JSON.parse(row.issuesJson) as Issue[], replayed: true } : null;
}

export function insertImport(input: ImportIssuesInput, authorId: UserId, plan: PlanId, projectKey: string): IssueImportResult {
  return getDb().transaction((tx) => {
    const existing = tx.select().from(issueImports).where(and(eq(issueImports.orgId, input.orgId), eq(issueImports.importKey, input.importKey))).get();
    if (existing) return { importKey: input.importKey, projectId: existing.projectId as ProjectId, issues: JSON.parse(existing.issuesJson) as Issue[], replayed: true };
    const used = tx.select({ value: count() }).from(issues).where(and(eq(issues.orgId, input.orgId), eq(issues.projectId, input.projectId), isNull(issues.archivedAt))).get()?.value ?? 0;
    if (wouldExceedLimit(plan, \"issuesPerProject\", used, input.rows.length)) throw new Error("'`Plan ${plan} allows no more issues in project ${projectKey}`);
    let number = (tx.select({ value: sql<number | null>`max(${issues.number})` }).from(issues).where(and(eq(issues.orgId, input.orgId), eq(issues.projectId, input.projectId))).get()?.value ?? 0);
    const memberRows = tx.select({ email: users.email, userId: users.id }).from(members).innerJoin(users, eq(users.id, members.userId)).where(and(eq(members.orgId, input.orgId), eq(members.status, "active"), isNull(members.archivedAt))).all();
    const byEmail = new Map(memberRows.map((m) => [m.email.toLowerCase(), m.userId]));
    const byName = new Map(tx.select().from(labels).where(eq(labels.orgId, input.orgId)).all().map((label) => [label.name, label.id as LabelId]));
    const stamp = toIsoTimestamp(new Date());
    const created: Issue[] = [];
    for (const item of input.rows) {
      const labelIds: LabelId[] = [];
      for (const name of new Set(item.labels)) {
        let id = byName.get(name);
        if (!id) {
          id = newId() as LabelId;
          tx.insert(labels).values({ id, orgId: input.orgId, name, color: "#94a3b8", description: null, createdAt: stamp, updatedAt: stamp }).run();
          byName.set(name, id);
        }
        labelIds.push(id);
      }
      const row = tx.insert(issues).values({ id: newId(), orgId: input.orgId, projectId: input.projectId, number: ++number, title: item.title, description: item.description, status: item.status, priority: item.priority, authorId, assigneeId: item.assigneeEmail ? byEmail.get(item.assigneeEmail.toLowerCase()) ?? null : null, parentId: null, estimate: null, dueAt: item.dueAt, startedAt: null, completedAt: null, createdAt: stamp, updatedAt: stamp }).returning().get();
      if (labelIds.length) tx.insert(issueLabels).values(labelIds.map((labelId) => ({ orgId: input.orgId, issueId: row.id, labelId }))).run();
      created.push(toIssue(row, labelIds));
    }
    tx.insert(issueImports).values({ orgId: input.orgId, importKey: input.importKey, projectId: input.projectId, issuesJson: JSON.stringify(created) }).run();
    return { importKey: input.importKey, projectId: input.projectId, issues: created, replayed: false };
  });
}
EOF
